<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
require_login();
$user=current_user();$pdo=db();
if(!$pdo){http_response_code(503);exit('Database unavailable.');}
if(!music_workspace_release_schema_v330_ready()||!music_workspace_resources_v330_schema_ready($pdo)){http_response_code(503);exit('Music Workspace database upgrade is required.');}
$requested=max(0,(int)($_GET['workspace']??$_POST['workspace_id']??0));
$workspace=music_workspace_resources_v330_resolve_active($pdo,$user,$requested);
if(!$workspace){http_response_code(403);exit('No accessible Music Workspace was found.');}
$workspaceId=(int)$workspace['id'];$role=music_workspace_resources_v330_member_role($pdo,$workspaceId,(int)$user['id']);$canManage=music_workspace_resources_v330_can_manage($pdo,$workspaceId,'releases',$user);

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!verify_csrf()){flash('error','Session expired. Try again.');redirect(url('/music-releases.php?workspace='.$workspaceId));}
    $action=(string)($_POST['action']??'');
    try{
        if($action==='save_release'){$id=music_workspace_resources_v331_save_release($pdo,$workspaceId,$user,$_POST);flash('notice','Release saved.');redirect(url('/music-releases.php?workspace='.$workspaceId.'&release='.$id));}
        if($action==='delete_release'){$id=max(0,(int)($_POST['release_id']??0));music_workspace_resources_v331_delete_release($pdo,$workspaceId,$id,$user);flash('notice','Release deleted.');redirect(url('/music-releases.php?workspace='.$workspaceId));}
        if($action==='add_item'){$releaseId=max(0,(int)($_POST['release_id']??0));music_workspace_resources_v331_add_release_item($pdo,$workspaceId,$releaseId,$user,$_POST);flash('notice','Release task added.');redirect(url('/music-releases.php?workspace='.$workspaceId.'&release='.$releaseId));}
        if($action==='item_status'){$releaseId=max(0,(int)($_POST['release_id']??0));$itemId=max(0,(int)($_POST['item_id']??0));music_workspace_resources_v331_set_release_item_status($pdo,$workspaceId,$releaseId,$itemId,$user,(string)($_POST['status']??''));flash('notice','Task updated.');redirect(url('/music-releases.php?workspace='.$workspaceId.'&release='.$releaseId));}
        throw new RuntimeException('Unknown Release Workspace action.');
    }catch(Throwable $e){flash('error',$e->getMessage());redirect(url('/music-releases.php?workspace='.$workspaceId));}
}

$workspaces=music_workspace_resources_v330_accessible_workspaces($pdo,$user);$releases=music_workspace_resources_v331_releases($pdo,$workspaceId,true);
$selectedId=max(0,(int)($_GET['release']??0));$selected=$selectedId>0?music_workspace_resources_v331_release($pdo,$workspaceId,$selectedId):null;if($selectedId>0&&!$selected){flash('error','Release not found in this Music Workspace.');redirect(url('/music-releases.php?workspace='.$workspaceId));}
$items=$selected?music_workspace_resources_v331_release_items($pdo,$workspaceId,(int)$selected['id']):[];$editing=isset($_GET['edit'])&&$selected;$new=isset($_GET['new']);
$types=music_workspace_resources_v331_release_types();$statuses=music_workspace_resources_v331_release_statuses();$priorities=music_workspace_resources_v331_release_priorities();$itemStatuses=music_workspace_resources_v331_release_item_statuses();
$memberHeaderUser=$user;$memberHeaderTitle='Release Workspace';$memberHeaderSubtitle=(string)$workspace['workspace_name'].' · '.ucfirst($role?:'member');$memberHeaderActions='';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VP3 | Release Workspace</title><link rel="stylesheet" href="<?= e(url('/chat.css?v=82')) ?>"><style>
.mr-main{background:#f7f7f8;min-width:0}.mr-wrap{max-width:1180px;margin:auto;padding:28px 24px 70px}.mr-top,.mr-actions,.mr-row,.mr-task{display:flex;gap:9px;align-items:center}.mr-top{justify-content:space-between;flex-wrap:wrap;margin-bottom:18px}.mr-top select,.mr-form input,.mr-form textarea,.mr-form select,.mr-task select{border:1px solid #dfe1e4;border-radius:10px;background:#fff;padding:10px;color:#202226}.mr-layout{display:grid;grid-template-columns:360px minmax(0,1fr);gap:16px}.mr-panel{background:#fff;border:1px solid #e1e3e6;border-radius:16px;padding:16px}.mr-release{display:block;text-decoration:none;color:inherit;border:1px solid #eceef0;border-radius:12px;padding:13px;margin-bottom:8px}.mr-release.active{border-color:#202226}.mr-release strong{display:block}.mr-meta{font-size:12px;color:#777b81;margin-top:5px}.mr-btn{display:inline-flex;text-decoration:none;border:1px solid #dadde1;border-radius:10px;background:#fff;color:#202226;padding:9px 12px;font-weight:750;cursor:pointer}.mr-btn.primary{background:#202226;color:#fff;border-color:#202226}.mr-detail h1{margin:4px 0 8px;font-size:30px;letter-spacing:-.03em}.mr-progress{height:8px;background:#eceef0;border-radius:99px;overflow:hidden;margin:14px 0}.mr-progress span{display:block;height:100%;background:#202226}.mr-tasks{display:grid;gap:8px;margin-top:18px}.mr-task{justify-content:space-between;border:1px solid #eceef0;border-radius:11px;padding:11px;flex-wrap:wrap}.mr-task strong{font-size:14px}.mr-form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.mr-form label{display:grid;gap:6px;font-size:12px;font-weight:750}.mr-form .wide{grid-column:1/-1}.mr-form textarea{min-height:90px}.mr-empty{color:#777b81;padding:22px;text-align:center}.mr-kicker{text-transform:uppercase;letter-spacing:.09em;font-size:10px;font-weight:850;color:#85888e}@media(max-width:850px){.mr-layout{grid-template-columns:1fr}.mr-form{grid-template-columns:1fr}.mr-form .wide{grid-column:auto}}
</style></head><body><div class="chat-app"><?php $workspaceSidebarUser=$user;$workspaceSidebarActive='music_workspace';require __DIR__.'/includes/workspace-sidebar-v82.php'; ?><div class="chat-sidebar-backdrop" id="chatSidebarBackdrop"></div><main class="chat-main mr-main"><?php require __DIR__.'/includes/member-header.php'; ?><div class="mr-wrap"><div class="mr-top"><form method="get"><label>Workspace <select name="workspace" onchange="this.form.submit()"><?php foreach($workspaces as $w): ?><option value="<?= (int)$w['id'] ?>" <?= (int)$w['id']===$workspaceId?'selected':'' ?>><?= e((string)$w['workspace_name']) ?><?= !empty($w['access_role'])?' · '.e((string)$w['access_role']):'' ?></option><?php endforeach; ?></select></label></form><div class="mr-actions"><a class="mr-btn" href="<?= e(url('/music-library.php?workspace='.$workspaceId)) ?>">Music Library</a><a class="mr-btn" href="<?= e(url('/music-workspace.php?workspace='.$workspaceId)) ?>">Workspace Home</a><?php if($canManage): ?><a class="mr-btn primary" href="<?= e(url('/music-releases.php?workspace='.$workspaceId.'&new=1#editor')) ?>">+ New release</a><?php endif; ?></div></div><div class="mr-layout"><aside class="mr-panel"><div class="mr-kicker">Release plans</div><?php foreach($releases as $release): ?><a class="mr-release <?= $selected&&(int)$selected['id']===(int)$release['id']?'active':'' ?>" href="<?= e(url('/music-releases.php?workspace='.$workspaceId.'&release='.(int)$release['id'])) ?>"><strong><?= e((string)$release['title']) ?></strong><div class="mr-meta"><?= e((string)($statuses[$release['status']]??ucfirst((string)$release['status']))) ?> · <?= e((string)($types[$release['release_type']]??ucfirst((string)$release['release_type']))) ?><?= !empty($release['target_date'])?' · '.e(date('M j, Y',strtotime((string)$release['target_date']))):'' ?></div><div class="mr-meta"><?= (int)$release['completed_count'] ?>/<?= (int)$release['item_count'] ?> tasks complete</div></a><?php endforeach; if(!$releases): ?><div class="mr-empty">No release plans yet.</div><?php endif; ?></aside><section class="mr-panel mr-detail">
<?php if($new||$editing): $form=$editing?$selected:[]; ?><div id="editor" class="mr-kicker"><?= $editing?'Edit release':'New release' ?></div><form method="post" class="mr-form"><?= csrf_field() ?><input type="hidden" name="workspace_id" value="<?= $workspaceId ?>"><input type="hidden" name="action" value="save_release"><input type="hidden" name="id" value="<?= (int)($form['id']??0) ?>"><label class="wide"><span>Release title</span><input name="title" maxlength="190" required value="<?= e((string)($form['title']??'')) ?>"></label><label><span>Type</span><select name="release_type"><?php foreach($types as $value=>$label): ?><option value="<?= e((string)$value) ?>" <?= (string)($form['release_type']??'single')===(string)$value?'selected':'' ?>><?= e((string)$label) ?></option><?php endforeach; ?></select></label><label><span>Status</span><select name="status"><?php foreach($statuses as $value=>$label): ?><option value="<?= e((string)$value) ?>" <?= (string)($form['status']??'planning')===(string)$value?'selected':'' ?>><?= e((string)$label) ?></option><?php endforeach; ?></select></label><label><span>Priority</span><select name="priority"><?php foreach($priorities as $value=>$label): ?><option value="<?= e((string)$value) ?>" <?= (string)($form['priority']??'normal')===(string)$value?'selected':'' ?>><?= e((string)$label) ?></option><?php endforeach; ?></select></label><label><span>Target date</span><input type="date" name="target_date" value="<?= !empty($form['target_date'])?e(date('Y-m-d',strtotime((string)$form['target_date']))):'' ?>"></label><label class="wide"><span>Agent goal</span><textarea name="agent_goal"><?= e((string)($form['agent_goal']??'')) ?></textarea></label><label class="wide"><span>Notes</span><textarea name="notes"><?= e((string)($form['notes']??'')) ?></textarea></label><div class="wide mr-actions"><button class="mr-btn primary" type="submit">Save release</button><a class="mr-btn" href="<?= e(url('/music-releases.php?workspace='.$workspaceId.(!empty($form['id'])?'&release='.(int)$form['id']:''))) ?>">Cancel</a></div></form>
<?php elseif($selected): $total=count($items);$done=count(array_filter($items,static fn(array $i):bool=>(string)$i['status']==='complete'));$pct=$total>0?(int)round(($done/$total)*100):0; ?><div class="mr-kicker"><?= e((string)($types[$selected['release_type']]??$selected['release_type'])) ?></div><h1><?= e((string)$selected['title']) ?></h1><div class="mr-meta"><?= e((string)($statuses[$selected['status']]??$selected['status'])) ?> · <?= e((string)($priorities[$selected['priority']]??$selected['priority'])) ?><?= !empty($selected['target_date'])?' · Target '.e(date('M j, Y',strtotime((string)$selected['target_date']))):'' ?></div><div class="mr-progress"><span style="width:<?= $pct ?>%"></span></div><div class="mr-meta"><?= $done ?>/<?= $total ?> tasks complete · <?= $pct ?>%</div><?php if(!empty($selected['agent_goal'])): ?><p><?= nl2br(e((string)$selected['agent_goal'])) ?></p><?php endif; ?><div class="mr-actions"><?php if($canManage): ?><a class="mr-btn" href="<?= e(url('/music-releases.php?workspace='.$workspaceId.'&release='.(int)$selected['id'].'&edit=1#editor')) ?>">Edit release</a><form method="post" onsubmit="return confirm('Delete this release plan and its tasks?')"><?= csrf_field() ?><input type="hidden" name="workspace_id" value="<?= $workspaceId ?>"><input type="hidden" name="action" value="delete_release"><input type="hidden" name="release_id" value="<?= (int)$selected['id'] ?>"><button class="mr-btn" type="submit">Delete</button></form><?php endif; ?></div><div class="mr-tasks"><?php foreach($items as $item): ?><div class="mr-task"><div><strong><?= e((string)$item['title']) ?></strong><div class="mr-meta"><?= !empty($item['due_at'])?'Due '.e(date('M j, Y',strtotime((string)$item['due_at']))):'No due date' ?></div></div><?php if($canManage): ?><form method="post" class="mr-actions"><?= csrf_field() ?><input type="hidden" name="workspace_id" value="<?= $workspaceId ?>"><input type="hidden" name="action" value="item_status"><input type="hidden" name="release_id" value="<?= (int)$selected['id'] ?>"><input type="hidden" name="item_id" value="<?= (int)$item['id'] ?>"><select name="status" onchange="this.form.submit()"><?php foreach($itemStatuses as $value=>$label): ?><option value="<?= e((string)$value) ?>" <?= (string)$item['status']===(string)$value?'selected':'' ?>><?= e((string)$label) ?></option><?php endforeach; ?></select></form><?php else: ?><span class="mr-meta"><?= e((string)($itemStatuses[$item['status']]??$item['status'])) ?></span><?php endif; ?></div><?php endforeach; if(!$items): ?><div class="mr-empty">No release tasks yet.</div><?php endif; ?></div><?php if($canManage): ?><form method="post" class="mr-form" style="margin-top:18px"><?= csrf_field() ?><input type="hidden" name="workspace_id" value="<?= $workspaceId ?>"><input type="hidden" name="action" value="add_item"><input type="hidden" name="release_id" value="<?= (int)$selected['id'] ?>"><label><span>New task</span><input name="title" maxlength="190" required></label><label><span>Due date</span><input type="date" name="due_at"></label><label class="wide"><span>Instructions</span><textarea name="instructions"></textarea></label><div class="wide"><button class="mr-btn primary" type="submit">Add task</button></div></form><?php endif; ?>
<?php else: ?><div class="mr-empty">Select a release plan, or create one to start the workspace release calendar.</div><?php endif; ?></section></div></div></main></div><script src="<?= e(url('/workspace-shell-v82.js?v=82')) ?>" defer></script></body></html>